    "hypotheses": [
        {
            "service": "payment-service",
            "kind": "runtime_fault",
            "mechanism": "Payment service is generating duplicate idempotency keys (adding '-retry' suffix) during retries, causing the payment provider to process them as separate transactions",
            "supporting": ["E3", "E10", "E11"],
            "refuting": ["E5", "E9"],
            "explains": ["I5_single_payment"],
            "repair_plan": [
                {
                    "action": "restart_service",
                    "params": {
                        "service": "payment-service"
                    }
                },
                {
                    "action": "refund_duplicate_payments",
                    "params": {}
                }
            ]
        }
    ],
    "summary": "Payment service runtime fault generates non-idempotent retry keys causing duplicate payments."
}
